SELECT coalesce(nullIf(toString(properties.utm_source),''),nullIf(toString(properties.$referring_domain),''),'Direct / unknown') AS Source, uniqExact(person_id) AS Visitors, count() AS Pageviews FROM events WHERE event = '$pageview' AND (properties.surface IS NULL OR properties.surface = 'web') AND (properties.environment IS NULL OR properties.environment = 'production') AND match(toString(properties.$current_url), '^https://(www[.])?ypr[.]app(/|$)') AND {filters} GROUP BY Source ORDER BY Visitors DESC LIMIT 30
